{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    min_sum = sum(seg['minimum'] for seg in segments)
    cap_sum = sum(seg['capacity'] for seg in segments)
    if budget < min_sum or budget > cap_sum:
        raise ValueError('Budget infeasible')
    allocations = []
    by_name = {}
    for seg in segments:
        alloc = seg['minimum']
        allocations.append(alloc)
        by_name[seg['name']] = alloc
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if allocations[i] < seg['capacity']:
                score = seg['importance'] / (allocations[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            raise ValueError('No capacity left')
        allocations[best_idx] += 1
        by_name[segments[best_idx]['name']] = allocations[best_idx]
        remaining -= 1
    return {'allocations': allocations, 'by_name': by_name, 'total': budget}"}
